// Operational checks and local change records. Actor identity requires future SSO integration.
const beforeHistoryPersist=persistRecords,beforeOperationsPage=showPage,beforeHistoryDetail=detail,beforeOperationsOpenForm=openForm,beforeOperationsSummary=openProjectSummary,beforeLifecycleSubmit=submitForm;
function readableTime(value){return new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',dateStyle:'short',timeStyle:'short'}).format(new Date(value))}
submitForm=function(e,id){const status=new FormData(e.target).get('status');if(status==='완료'){const months=PlanModel.periodMonths(document.querySelector('#startDate').value,document.querySelector('#endDate').value),existing=data.find(x=>x.id===id);if(!months.length||PlanModel.percent(existing?.monthly?.[months.at(-1)]?.actual)!==100){e.preventDefault();showRegistrationErrors([{field:'status',message:'완료 처리 전에 종료 월의 누적 실적을 100%로 입력해 주세요.'}]);return}}return beforeLifecycleSubmit(e,id)};
document.querySelector('#performanceNav').insertAdjacentHTML('beforebegin','<div id="operationsNav" class="dashnav" role="button" tabindex="0" onclick="showPage(\'operations\')" onkeydown="if(event.key===\'Enter\')showPage(\'operations\')">☷ &nbsp;운영 인박스</div>');
document.querySelector('#listPage .integration-utility').insertAdjacentHTML('beforebegin','<div class="operations-entry"><div><strong>확인할 일부터 처리하세요</strong><span>실적 미입력과 지연 과제, 목표 계획 점검 항목을 모았습니다.</span></div><button class="secondary" onclick="showPage(\'operations\')">운영 인박스 열기</button></div>');
document.querySelector('#governancePage').insertAdjacentHTML('afterend','<main id="operationsPage" class="main" hidden></main>');
let operationsMonth=monthNow(),operationsTeam='',operationsPm='',operationsKind='';
showPage=function(page){document.querySelector('#operationsPage').hidden=page!=='operations';document.querySelector('#operationsNav').classList.toggle('selected',page==='operations');beforeOperationsPage(page);if(page==='operations')renderOperations()};
openForm=function(id){const fromInbox=!document.querySelector('#operationsPage').hidden;beforeOperationsOpenForm(id);if(fromInbox)registrationReturn='operations'};
openProjectSummary=function(id){const fromInbox=!document.querySelector('#operationsPage').hidden;beforeOperationsSummary(id);if(fromInbox)projectAiReturn='operations'};
function changeOperationsFilter(name,value){if(name==='month')operationsMonth=PlanModel.months(value,value).length&&value<=monthNow()?value:monthNow();if(name==='team')operationsTeam=value;if(name==='pm')operationsPm=value;if(name==='kind')operationsKind=value;renderOperations()}
function renderOperations(){const result=OperationsModel.buildInbox(data,{month:operationsMonth,team:operationsTeam,pm:operationsPm}),items=operationsKind?result.items.filter(i=>i.kind===operationsKind):result.items;const teams=[...new Set(data.filter(x=>!x.archivedAt).map(x=>x.team).filter(Boolean))].sort(),pms=[...new Set(data.filter(x=>!x.archivedAt).map(x=>x.pm).filter(Boolean))].sort();document.querySelector('#operationsPage').innerHTML=`<div class="top"><div><div class="eyebrow">OPERATIONS INBOX</div><h1>운영 인박스</h1><p>확인이 필요한 과제를 찾아 바로 다음 작업으로 이어가세요.</p></div><button class="secondary" onclick="showPage('list')">전체 과제 보기</button></div><div class="banner">기준 월까지의 입력 데이터를 점검합니다. 알림 발송과 SSO 담당자 연결은 연동 전입니다.</div><div class="ops-filters"><div class="field"><label for="opsMonth">점검 기준 월</label><input id="opsMonth" type="month" max="${monthNow()}" value="${esc(operationsMonth)}" onchange="changeOperationsFilter('month',this.value)"></div><div class="field"><label for="opsTeam">소속 팀</label><select id="opsTeam" onchange="changeOperationsFilter('team',this.value)"><option value="">전체 팀</option>${teams.map(t=>`<option ${operationsTeam===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="field"><label for="opsPm">PM</label><select id="opsPm" onchange="changeOperationsFilter('pm',this.value)"><option value="">전체 PM</option>${pms.map(p=>`<option ${operationsPm===p?'selected':''}>${esc(p)}</option>`).join('')}</select></div></div><div class="ops-counts">${[['','전체 확인 항목',result.counts.total],['missing','실적 미입력',result.counts.missing],['late','누적 지연',result.counts.late],['plan','계획 점검',result.counts.plan],['complete','완료 상태 점검',result.counts.complete||0]].map(([kind,label,n])=>`<button class="ops-counter ${operationsKind===kind?'active':''}" onclick="changeOperationsFilter('kind','${kind}')"><span>${label}</span><strong>${n}</strong></button>`).join('')}</div><section class="panel"><div class="panelhead"><div><h2>확인할 일</h2><p class="integration-help">${items.length}개 항목 · 같은 과제에 여러 확인 항목이 있을 수 있습니다. 보류·완료 과제는 정기 실적 요청에서 제외합니다.</p></div></div>${items.length?`<div class="ops-items">${items.map((item,index)=>`<article class="ops-item"><div class="ops-item-top"><span class="ops-kind ${item.kind}">${esc(item.label)}</span><span>${esc(item.team||'팀 미지정')} · PM ${esc(item.pm||'미지정')}</span></div><h3>${esc(item.title)}</h3><p>${esc(item.description)}</p><div class="ops-item-actions"><button class="text-button" data-ops-detail="${index}">과제 상세</button><button class="secondary" data-ops-action="${index}">${item.kind==='plan'?'목표 계획 확인':item.kind==='complete'?'상태 확인':'실적 입력'}</button></div></article>`).join('')}</div>`:'<div class="empty">현재 조건에서 확인할 항목이 없습니다.</div>'}</section><p class="ops-footnote">미입력은 0%로 계산하지 않습니다. 최근 입력 실적에 미달이 남아 있으면 미입력과 지연을 함께 표시합니다.</p>`;document.querySelectorAll('[data-ops-detail]').forEach(b=>b.onclick=()=>detail(items[Number(b.dataset.opsDetail)].projectId));document.querySelectorAll('[data-ops-action]').forEach(b=>b.onclick=()=>openInboxAction(items[Number(b.dataset.opsAction)]))}
function openInboxAction(item){if(item.kind==='plan'||item.kind==='complete'){openForm(item.projectId);return}openPerformance(item.projectId);const month=item.months?.[0]||operationsMonth,year=Number(month.slice(0,4));const select=document.querySelector('#reportYear');if(select&&[...select.options].some(o=>o.value===String(year))){select.value=String(year);changeReportYear(year)}window.StepUI?.selectReportMonth?.(month);const field=document.querySelector(`[data-report-month="${month}"][data-report-kind="actual"]`);field?.focus()}
function historyMarkup(x){const events=x._history||[];return `<details class="history-panel"><summary>활동 이력 <span>${events.length}건</span></summary><p class="history-notice">이 브라우저의 변경 기록입니다. 인증된 변경자 기록은 SSO·서버 연결 후 적용됩니다. 전체 기록을 보관합니다.</p>${events.length?events.map(e=>`<article class="history-event"><div><strong>${esc(e.action)}</strong><span>${esc(readableTime(e.at))} · ${esc(e.actor)}</span></div><ul>${e.changes.map(c=>`<li><strong>${esc(c.label)}</strong><span>${esc(historyValue(c.before))} <i>→</i> ${esc(historyValue(c.after))}</span></li>`).join('')}</ul></article>`).join(''):'<p class="integration-help">변경 기록 기능을 추가한 이후의 저장부터 표시됩니다.</p>'}</details>`}
function historyValue(value){const text=Array.isArray(value)?value.join(', '):value==null||value===''?'미입력':String(value);return text.length>700?text.slice(0,700)+'…':text}
detail=function(id){beforeHistoryDetail(id);const x=data.find(a=>a.id===id),holder=document.createElement('section');holder.innerHTML=historyMarkup(x);document.querySelector('#dialog .actions').before(holder)};
const refreshBeforeLifecycle=refreshProgress;
refreshProgress=function(){refreshBeforeLifecycle();document.querySelectorAll('tr[data-id]').forEach(row=>{const x=data.find(a=>a.id===row.dataset.id);row.cells[5].insertAdjacentHTML('afterbegin',`<span class="lifecycle-label">${esc(x?.status||'계획')}</span>`)});document.querySelector('#listPage thead th:last-child').textContent='운영 상태 · 진척'};
render();
